mapper.select:
SELECT k.*, mt.code AS material_code, mt.name AS material_name, mt.spec AS material_spec FROM ecom_owh_sku k LEFT JOIN wms_material mt ON mt.id = k.material_id WHERE k.account_id = #{accountId}
AND (k.owh_sku LIKE CONCAT('%', #{keyword}, '%') OR mt.code LIKE CONCAT('%', #{keyword}, '%') OR mt.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY mt.code
